##################################################################################################################
# TEST CONFIG FILE
##################################################################################################################
# config file
# name = value							# '=' name 변수에 value 값 입력
# name = "this is" 'string'				# string = "", ''로 표시
#										# 개행문자 혹은 comment까지 값으로 인식
# 특수 문자  \a \b \f \n \r \t \v \\ \' \" \? \$ \xHEX \0OCT \DEC \BBIT
# $ - 변수에 저장된 값을 가져온다. ( 1 환경변수,  2 cfg내 선언변수, 3 현재 section 선언변수)
###################################################################################################################
# name1		= value										# comment
# name2		= "this is string"	' continue'				# "string" 'string'
# name3		= "특수문자 \B110010 \x00000032 \062 \50" 	# comment
# name4		= "환경변수 $HOME $name3"					# $환경변수, $변수
# section												# section 
# {
#	s_m1	= sv1 
#	s2		{m1=v1 s3{m2=v2}}							# deep section
# }
# [win_section]											# win section
# win_name1	= win_value1
###################################################################################################################
# field format
###################################################################################################################
# 각 필드는 strtok로 불러오기 때문에 데이타가 없는 필드라도 
#  구분자(:) 사이에 스페이스(' ')나 도트('.')가 꼭 있어야 한다.
# field number
# field name
# x position
# y position
# view size
# data size : malloc 되는 size
# attribute 
#    WIN_ATTR_BLACK              0
#    WIN_ATTR_RED                1
#    WIN_ATTR_GREEN              2
#    WIN_ATTR_YELLOW             3
#    WIN_ATTR_BLUE               4
#    WIN_ATTR_MAGENTA            5
#    WIN_ATTR_CYAN               6
#    WIN_ATTR_WHITE              7
#    WIN_ATTR_BRIGHT             8
#         u    
#         n    
#      r  dcc  
#      e ieord 
#      v trnoeb
#    fbebalcsll
#    oaroliosei
#    rcslinaetn
#    ekedceldek
#	:7010000000:
#
#
# type : field type
#        cp 
#     s  oo 
#     ei mi 
#    mln pnt
#    eepmaty
#    ncuarep
#    uttpere
#	:0001000:
#
#   type = 
#   INT            '1'
#   FLOAT          '2'
#   LONG           '3'
#   LONG_LONG      '4'
#   DOUBLE         '5'
# format : data를 표시하기위한 printf 포맷
# filler : 모양 맞추기 위한 field ...
# initial data
#	"base	:name		:pos_x	:pos_y	:"     - base 아래 필드의 상대 x,y 위치를 세팅: x + pos_x, y + pos_y
#
#	"line	:start		:s_y	:e_y	:gap"  - 라인 반복 시작 - s_y(start y),e_y(end y) name=name_y gap(증가값)
#	"line	:end		:		:		:"     - 라인 반복 끝   
#	-----> name=name_순번, id=(id*1000)+순번
###################################################################################################################
map
{
	win_size	= 10, 12, 120, 20							# x, y, size_x, size_y
	timeout		= 250000								# select timeout (micro second)
}

screen
{
"                                                                                       "
"+-------------------------------------------------------------------------------------+"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"|                                                                                     |"
"+-------------------------------------------------------------------------------------+"
}

